# Guide pages (puja vidhi, melas). Executed inside build.py after gaps_section
# (uses add, band, sec_head, faq_html, faq_ld, e, SITE, video_cards, V).

def _g_ul(items):
    return '<ul class="library">' + "".join(f'<li><a href="{h}"><strong>{e(t)}</strong><span>{e(s)}</span></a></li>' for h, t, s in items) + "</ul>"

def _g_steps(items):
    return '<ol class="steps">' + "".join(f"<li>{x}</li>" for x in items) + "</ol>"

def _g_table(head, rows):
    th = "".join(f"<th>{e(h)}</th>" for h in head)
    tr = "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
    return f'<div class="tbl"><table class="ptable"><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'

